// KISWAHILI GRADE 5: skills, prerequisites and the misconception library (authoring source).
// Written offline by Claude (12 Nov 2026), no model call. Everything here is DRAFT until a native
// Kiswahili speaker who teaches Kiswahili reviews it (docs/qa/kiswahili-g5-review-2026-11-12.md and
// docs/qa/kiswahili-g5-native-check-2026-11-12.md say what to check).
// scripts/build-kiswahili-g5.mjs merges it into curriculum/kiswahili/g5.json (HOREB owns that file).
// Keys: 'SARUFI.T1_AINA_ZA_NOMINO' is the sub-strand KISW.G5.SARUFI.T1_AINA_ZA_NOMINO (exact code, no prefix match:
// the design truncates names, so _2 and _3 are separate sub-strands).
// The reviewer-facing fields are in English; examples and what a child is told are in Kiswahili sanifu.
// ============================================================================
export const TO_CONFIRM = 'common learner error; to confirm by a native Kiswahili teacher';
export const INTERFERENCE = 'English or mother-tongue influence on Kiswahili (to confirm by a native Kiswahili teacher)';

// S(sub, id, name, outcomes, mastery, questionForms, prerequisites, thinking)
const S = (sub, id, name, outcomes, mastery, forms, pre = [], thinking = ['recall']) => ({ sub, id, name, outcomes, mastery, forms, pre, thinking });
// M(skill, code, error, question, wrong, right, cause, reveals, help, feedback, source)
const M = (skill, code, error, question, wrong, right, cause, reveals, help, feedback, source = TO_CONFIRM) => ({ skill, code, error, example: { question, wrong_answer: wrong, correct_answer: right }, cause, reveals, help, feedback, source });

